// Shared pieces of the song readers (id3.ts, mp4.ts, flac.ts, wav.ts): what
// they find, and the byte and text helpers they all need. Everything under
// music/ is pure, so it can be tested with generated bytes and no phone.

import type { AudioFormat } from '../../models/types';
import { decodeAs, decodeGbkFast, decodeText } from '../decodeText';

export type { AudioFormat };

export interface CoverImage {
  bytes: Uint8Array;
  extension: string;
}

/** What a song's tags say. Missing text is '' and missing numbers are null. */
export interface AudioTags {
  title: string;
  artist: string;
  album: string;
  albumArtist: string;
  /** Four digits, or ''. */
  year: string;
  trackNumber: number | null;
  discNumber: number | null;
  /** Plain (untimed) lyrics stored in the file, or ''. */
  lyrics: string;
  cover: CoverImage | null;
}

export const EMPTY_TAGS: AudioTags = {
  title: '',
  artist: '',
  album: '',
  albumArtist: '',
  year: '',
  trackNumber: null,
  discNumber: null,
  lyrics: '',
  cover: null,
};

/** Fills gaps in `main` from `fallback`, e.g. ID3v2 tags first, then ID3v1. */
export function mergeTags(main: AudioTags, fallback: AudioTags): AudioTags {
  return {
    title: main.title || fallback.title,
    artist: main.artist || fallback.artist,
    album: main.album || fallback.album,
    albumArtist: main.albumArtist || fallback.albumArtist,
    year: main.year || fallback.year,
    trackNumber: main.trackNumber ?? fallback.trackNumber,
    discNumber: main.discNumber ?? fallback.discNumber,
    lyrics: main.lyrics || fallback.lyrics,
    cover: main.cover ?? fallback.cover,
  };
}

export type AudioErrorCode = 'notAudio' | 'video';

export class AudioError extends Error {
  constructor(readonly code: AudioErrorCode) {
    super(`Audio error: ${code}`);
  }
}

/** "3/12" → 3, "07" → 7; null if there's no positive number at the start. */
export function leadingNumber(text: string): number | null {
  const match = /^\s*(\d{1,4})/.exec(text);
  const n = match ? Number(match[1]) : 0;
  return n > 0 ? n : null;
}

/** The first four-digit year in a date like "2026-11-02" or "2026". */
export function yearOf(text: string): string {
  return /\b(\d{4})\b/.exec(text)?.[1] ?? '';
}

export function ascii(bytes: Uint8Array, at: number, length: number): string {
  return String.fromCharCode(...bytes.subarray(at, at + length));
}

export function u32(bytes: Uint8Array, at: number): number {
  return ((bytes[at] << 24) | (bytes[at + 1] << 16) | (bytes[at + 2] << 8) | bytes[at + 3]) >>> 0;
}

export function u32le(bytes: Uint8Array, at: number): number {
  return (bytes[at] | (bytes[at + 1] << 8) | (bytes[at + 2] << 16) | (bytes[at + 3] << 24)) >>> 0;
}

/** Image type from the first bytes, for covers that don't say (or say wrongly). */
export function coverOf(bytes: Uint8Array, mimeType = ''): CoverImage | null {
  if (bytes.length < 8) return null;
  if (bytes[0] === 0xff && bytes[1] === 0xd8) return { bytes, extension: 'jpg' };
  if (bytes[0] === 0x89 && ascii(bytes, 1, 3) === 'PNG') return { bytes, extension: 'png' };
  if (ascii(bytes, 0, 4) === 'GIF8') return { bytes, extension: 'gif' };
  if (ascii(bytes, 0, 4) === 'RIFF' && ascii(bytes, 8, 4) === 'WEBP') return { bytes, extension: 'webp' };
  if (/jpe?g/i.test(mimeType)) return { bytes, extension: 'jpg' };
  if (/png/i.test(mimeType)) return { bytes, extension: 'png' };
  return null;
}

/**
 * Text that claims to be Latin-1. Many Chinese files store GBK there instead,
 * so if every byte above 0x7F comes in a pair that's a GB2312 character (both
 * bytes 0xA1–0xFE), it's read as GBK. Accented Western text almost never looks
 * like that: an accent is followed by a plain letter.
 */
export function decodeLatin1OrGbk(bytes: Uint8Array): string {
  let high = false;
  let gbkLike = true;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] < 0x80) continue;
    high = true;
    const trail = bytes[i + 1];
    if (bytes[i] < 0xa1 || bytes[i] > 0xfe || trail === undefined || trail < 0xa1 || trail > 0xfe) {
      gbkLike = false;
      break;
    }
    i++;
  }
  if (high && gbkLike) {
    const text = decodeGbkFast(bytes);
    if (text !== null) return text;
  }
  // Some taggers write UTF-8 while claiming Latin-1.
  if (high) {
    const decoded = decodeText(bytes);
    if (decoded.encoding === 'utf-8') return decoded.text;
  }
  return String.fromCharCode(...bytes);
}

export function decodeUtf8(bytes: Uint8Array): string {
  return decodeAs(bytes, 'utf-8');
}

/** Removes the trailing zero bytes and spaces that fixed-size and C-style fields leave. */
export function clean(text: string): string {
  return text.replace(/[\u0000\s]+$/, '').trim();
}
